param([switch]$Apply)
$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.IO.Compression.FileSystem
$root=Split-Path $PSScriptRoot -Parent
$backup=Join-Path $root ('Review Backups/system-alignment-'+(Get-Date -Format 'yyyyMMdd-HHmmss'))
New-Item -ItemType Directory -Path $backup -Force|Out-Null
$w='http://schemas.openxmlformats.org/wordprocessingml/2006/main'
foreach($chapter in @(1,3)) {
 $source=Join-Path $root "Chapter $chapter.docx"
 Copy-Item -LiteralPath $source -Destination (Join-Path $backup "Chapter $chapter original.docx")
 $work=Join-Path $backup "Chapter $chapter updated.docx"
 Copy-Item -LiteralPath $source -Destination $work
 $zip=[IO.Compression.ZipFile]::Open($work,'Update')
 try {
  $reader=[IO.StreamReader]::new($zip.GetEntry('word/document.xml').Open())
  try {[xml]$doc=$reader.ReadToEnd()} finally {$reader.Dispose()}
  $ns=[Xml.XmlNamespaceManager]::new($doc.NameTable);$ns.AddNamespace('w',$w)
  $paras=@($doc.SelectNodes('//w:body//w:p',$ns))
  function Text($p) {($p.SelectNodes('.//w:t',$ns)|ForEach-Object InnerText)-join ''}
  function Put($p,$text) {
   $nodes=@($p.SelectNodes('.//w:t',$ns));if(-not $nodes.Count){throw 'No text run in target paragraph'}
   $nodes[0].InnerText=$text
   foreach($node in @($nodes|Select-Object -Skip 1)){$node.InnerText=''}
  }
  function ReplacePrefix($prefix,$text) {
   $matches=@($paras|Where-Object {(Text $_).Trim().StartsWith($prefix)})
   if($matches.Count -ne 1){throw "Expected one paragraph starting '$prefix'; found $($matches.Count)"}
   Put $matches[0] $text
  }
  function AddAfter($prefix,$text) {
   $matches=@($paras|Where-Object {(Text $_).Trim().StartsWith($prefix)})
   if($matches.Count -ne 1){throw "Ambiguous insertion anchor: $prefix"}
   $p=$matches[0].CloneNode($true)
   foreach($bookmark in @($p.SelectNodes('.//w:bookmarkStart|.//w:bookmarkEnd',$ns))){[void]$bookmark.ParentNode.RemoveChild($bookmark)}
   Put $p $text
   [void]$matches[0].ParentNode.InsertAfter($p,$matches[0])
  }
  $tablesBefore=@($doc.SelectNodes('//w:body/w:tbl',$ns))
  $dictionaryBefore=(@($tablesBefore|Select-Object -Skip 5|ForEach-Object OuterXml))-join ''
  $drawingsBefore=$doc.SelectNodes('//w:drawing',$ns).Count
  if($chapter -eq 1) {
   ReplacePrefix 'The system included QR code-based attendance monitoring.' 'The system included QR code-based attendance monitoring. Authorized administrators and staff could record member check-ins and check-outs using a supported computer or phone camera. Staff could also search by member name or Gmail, select the matching record, and submit attendance using its unique member identifier. Search alone did not record attendance or provide general member-profile access. A phone required an authorized operator sign-in and an administrator-managed pairing. Each phone browser installation used its own pairing QR and record. A setup QR expired after ten minutes; successful phone pairing remained valid for thirty days unless removed earlier. Paired phones and unexpired pending QRs shared the configured slot limit, initially set to two. A pending QR reserved one slot until paired, ended, or expired. The attendance scanner could be opened through a separate installation link and installed as a Progressive Web App; reinstalling in the same browser could reuse an available, active saved pairing. Cleared browser data, removed pairings, or expired connections could require administrator-assisted pairing again. Attendance without a check-out from a previous Philippine calendar date was displayed as Incomplete; the system did not invent a missing check-out timestamp.'
   AddAfter 'The system also included product inventory and sales features.' 'Low-stock alerts used product-form and selling-unit rules, with conversion from the configured stock unit, including pounds, to the applicable base unit. Initial thresholds were 1,000 g for protein powder; 250 g for creatine, pre-workout, amino-acid, and vitamin powders; 500 g for other powders; 1,000 ml for liquids; 30 individually sold capsules or tablets; four boxes; ten other supplement items; and four merchandise items per product or size. These were configurable-in-code starting alert levels, not calculated forecasts or proven optimal reorder points. Actual reorder levels required sales-demand and supplier-lead-time information.'
   ReplacePrefix 'Account creation included validation' 'Account creation included validation of required information, matching password confirmation, password-strength requirements, and duplicate email addresses or, where supported, usernames. Staff account registration collected first name, optional middle initial, and last name separately and combined them into the existing full-name record. Administrator and staff walk-in member forms used the same separate-name arrangement without introducing separate database name columns. Names containing numeric characters were rejected. Member password creation and updates used the implemented eight-character minimum; staff-account creation used a twelve-character minimum, with the applicable uppercase, lowercase, digit, and symbol requirements. Show/hide controls improved password entry without storing readable passwords. Administrator and staff accounts had to be active to use their protected functions. Members remained restricted to their own permitted personal information.'
   AddAfter 'Dashboard sessions and attendance-scanner sessions were tracked separately.' 'The activity-log implementation covered operational record changes and was extended to security and access events: rejected credential attempts, rate-limit rejections, member and scanner sign-ins and explicit sign-out requests, successful password updates, password-reset requests, and report-export requests. Administrators could filter and review these events; passwords, reset tokens, and report contents were excluded. Export logging represented a request rather than verified file-download completion, and closing a browser was not treated as a reliable explicit sign-out. The November 10, 2026 source changes required their database migration and authentication-function deployment before the expanded coverage could be claimed for production. Reset-request capture also depended on Supabase database Auth audit storage being enabled.'
   AddAfter 'Phone Pairing. The administrator-authorized connection' 'Progressive Web App (PWA). The installable browser-based attendance scanner that can be launched from a device home screen. Installation does not replace operator authentication, phone pairing, or the internet connection required to save attendance.'
  } else {
   ReplacePrefix 'This chapter discusses the methodology used to develop' "This chapter discusses the methodology used to develop IronGrind: A Fitness Gym Membership and Operations Management System for Iron Grind Fitness Gym in Purok Mangga, Sulangon, Dapitan City, Zamboanga del Norte. IronGrind is a web application with an installable attendance-scanner component. This chapter describes the development process, system requirements, design, data organization, and evaluation procedures. The system organizes membership applications and records, membership periods and renewals, attendance, products, sales, reports, and activity review. Its development is organized using Agile, with work planned and delivered incrementally. Proposed evaluation activities are distinguished from results that have not yet been collected."
   AddAfter 'Implementation prepares verified increments for operational use.' 'Deployment status must be checked separately for subsequent revisions. The November 10, 2026 source review added server-audited member email sign-in, security-event functions and triggers, and corresponding interface changes. Deploy the security-activity migration and both the new member-password-login and updated admin-username-login Edge Functions before releasing the dependent web client. Password-reset-request capture requires database Auth audit storage. These local implementation changes and isolated tests do not establish that the production database, functions, and Vercel client already contain this revision.'
   ReplacePrefix 'Authorized operators record QR check-in/out and read permitted visits;' 'Authorized operators record check-in/out through QR scanning or staff name/Gmail lookup followed by explicit member selection; members read only their own visits. Administrators manage pairing. Scanner installation is separate from pairing and operator sign-in.'
   ReplacePrefix 'Administrators maintain products, prices, units, stock and active state.' 'Administrators maintain products, prices, units, stock and active state. Inventory cards separate selling price, stock on hand and unit-converted low-stock thresholds, with product search and status filters. Members browse active products. Staff read a sales catalog grouped into supplement forms and merchandise without inventory-maintenance access.'
   ReplacePrefix 'Administrators review recorded actions, including staff-account changes' 'Administrators review operational and configured security events using account, category, action and date filters. Clear action labels and category badges summarize events; expandable Details contains descriptions, identifiers and changed fields. This read-only function does not perform logged operations.'
   ReplacePrefix 'Operator member QR and attendance query;' 'Operator QR or staff name/Gmail search, explicit matched-member selection and attendance query; member own-history query; administrator pairing setup, settings or removal request.'
   ReplacePrefix 'Filtered recorded activity showing time, actor, action, area' 'Filtered events showing Philippine date/time, actor, readable action, category and affected record; expandable descriptions, record/account identifiers and changed fields; paging and reset controls.'
   ReplacePrefix 'QR Attendance has different member and operator uses.' 'QR Attendance has different member and operator uses. Members display their own QR code and view their own attendance history. Authorized operators scan member QRs, while staff may alternatively search by name or Gmail, select the correct matching member and explicitly record attendance. The selected unique member identifier is submitted to the attendance service, avoiding reliance on potentially shared names. A search does not itself record a visit or grant profile-viewing rights. The service checks the member and current visit state before recording a check-in or check-out with its timestamp and operator. Staff feedback identifies the member, outcome and Philippine display time; the database timestamp remains the saved event time. Administrator-managed phone pairing is separate from operator sign-in and installation of the scanner PWA. Members cannot record their own attendance.'
   ReplacePrefix '4. Counter and attendance operations.' '4. Counter and attendance operations. Administrator and staff walk-in registration collect first name, optional middle initial and last name, combine them into the existing full-name value, and submit the membership details to an authorized service. Direct renewal and active-plan change use limited lookup rather than a profile screen; staff confirm the selected member, current plan, payment amount and replacement dates before saving. Attendance uses a member QR or staff name/Gmail lookup with explicit selection. The service checks the member and open visit before recording check-in/out and the responsible operator. An earlier-date visit without check-out is shown as Incomplete without inventing an exit time. Phone pairing, operator authentication and PWA installation are separate steps.'
   ReplacePrefix '8. Record Membership Attendance.' '8. Record Membership Attendance. An administrator or authorized staff operator scans a member QR using a supported camera. Staff can also search by member name or Gmail, select the matching member and record attendance. The service validates the supplied member identifier and visit state, records check-in/out and the responsible operator, and returns the result.'
   AddAfter '17. Activity Logs and Related Administration.' 'Expanded audit coverage and presentation. Operational writes continue to generate database audit events. The security extension adds server-recorded failed credential attempts and rate-limit rejections, member and scanner session events, successful password updates, recovery requests and report-export requests. Failed attempts are attributed to an unverified visitor rather than assumed to be the account owner. Password-change events identify the affected account without storing its password or hash in the activity log; the authenticated actor is used when available, otherwise the authentication service is shown. Recovery requests do not prove that the requester owns an account or that an email was delivered. Report export means a request, not verified browser-download completion. The administrator viewer keeps action labels distinct from descriptions and places technical identifiers and changed-field names inside expandable Details. Account, grouped category, action and Philippine date-range filters operate with server-side pagination. Searches and routine page views are not comprehensively logged. Database and Edge Function deployment, plus enabled Auth database audit storage for recovery requests, are required for this expanded coverage.'
   AddAfter '12. Manage Products and Inventory.' 'Low-stock policy and catalog organization. The administrator inventory view separates selling price from stock on hand and shows low-stock alerts in the configured stock unit. Powder alerts use 1,000 g for protein; 250 g for creatine, pre-workout, amino-acid and vitamin powders; and 500 g for other powders. Liquid alerts use 1,000 ml; individually sold capsules/tablets use 30 pieces; boxed supplements use four boxes; other supplement items use ten items; and merchandise uses four items per product/size. Product form and sale unit take precedence over supplement type. Pounds and ounces are converted before comparison, so the same physical quantity has the same alert status regardless of entry unit. Values at or below the threshold trigger an alert; zero stock is distinguished as unavailable. Thresholds are starting policy values in application code, not stored threshold columns or demand-based reorder forecasts. Staff catalog sections separate Supplements into Powders, Capsules, Tablets, Liquids/drinks and Other, with Merchandise separately. Saved form metadata determines grouping; legacy gram or milliliter products can use a unit-based fallback, while an unidentified form remains Other.'
   AddAfter 'Successful physical multi-phone operation' 'Prototype currency note. The supplied screenshots preserve earlier interface states. Subsequent source revisions added split administrator member-name inputs, inventory search and unit-aware alert cards, staff attendance lookup, supplement-form catalog sections, request filters, membership confirmations, scanner reinstall access, password visibility controls and the revised activity viewer. The existing images must be recaptured from the deployed revision before they are presented as screenshots of those new controls. Their descriptions distinguish captured evidence from later implementation; no image is altered to simulate a new interface.'
   ReplacePrefix "The administrator's complete Add New Member dialog supports" "The administrator's complete Add New Member dialog supports counter registration using personal and emergency-contact details, membership dates, signature and portal credentials. This earlier capture shows a single full-name input. The current source revision separates first name, optional middle initial and last name in both administrator and staff member-registration forms, then combines the values for the existing full-name database field. Fresh captures are required to illustrate the revision. Submission creates the applicable records through the authorized service and records the in-person transaction; it does not grant personal-profile editing rights. The complete captured dialog is followed by enlarged details."
   ReplacePrefix 'This detail enlarges the personal and emergency-contact inputs' 'This detail enlarges the personal and emergency-contact inputs of the earlier administrator walk-in dialog in Figure 12. It shows the former full-name input, birth and contact information, height and weight, and emergency-contact details. The current source uses separate first name, optional middle initial and last name; this older image must not be presented as showing that revision. The inputs support new member creation rather than editing an existing personal profile.'
   ReplacePrefix "The administrator's Staff Accounts page combines" "The administrator's Staff Accounts page combines account creation and the staff directory. The form separates first name, optional middle initial and last name and collects assigned username, Gmail, contact information, password and confirmation. The current source also provides directory search by name, username or email and labeled expandable account details; these additions are not established by the earlier capture. Administrator controls govern staff-account access rather than member self-profile editing. The captured attendance-only subtitle is superseded; staff also have the documented counter, product-sale and request-review tasks."
   ReplacePrefix 'The complete Activity Logs screen shows' 'The earlier Activity Logs capture shows actor, area and date filters, Apply/Clear controls, event rows, refresh and pagination. The revised source adds grouped categories, an action filter, Reset filters, persistent readable action labels, category badges and expandable Details for identifiers, descriptions and changed fields. On narrow screens, events use stacked layouts. Times are displayed in Philippine time. This remains an administrator-only read function, and opening an entry does not execute its recorded action. A new screenshot is needed to show the revised viewer; sample rows are not a formal security evaluation.'
   ReplacePrefix 'The complete staff Product sales page combines' 'The complete staff Product sales capture combines the sale-entry form, own recent sales and the permitted product catalog. The current source additionally displays selected stock and sale units and groups supplements into powder, capsule, tablet, liquid/drink and other sections, with merchandise separately. These newer controls require refreshed screenshots. The service checks the item, quantity, unit and stock before saving a sale and deduction. Staff can record sales and review their own records without product-edit, restock, archive or unrestricted sales-review privileges.'
  }
  if($doc.SelectNodes('//w:drawing',$ns).Count -ne $drawingsBefore){throw 'Figure count changed'}
  if($chapter -eq 3 -and ((@($doc.SelectNodes('//w:body/w:tbl',$ns)|Select-Object -Skip 5|ForEach-Object OuterXml))-join '') -cne $dictionaryBefore){throw 'Data dictionary changed unexpectedly'}
  $entry=$zip.GetEntry('word/document.xml');$stream=$entry.Open();$stream.SetLength(0)
  $writer=[IO.StreamWriter]::new($stream,[Text.UTF8Encoding]::new($false));try{$doc.Save($writer)}finally{$writer.Dispose()}
 } finally {$zip.Dispose()}
}
if($Apply) {
 # Verify both destinations can be replaced before touching either original.
 foreach($chapter in @(1,3)) {
  $stream=[IO.File]::Open((Join-Path $root "Chapter $chapter.docx"),'Open','ReadWrite','None');$stream.Dispose()
 }
 foreach($chapter in @(1,3)) {Copy-Item -LiteralPath (Join-Path $backup "Chapter $chapter updated.docx") -Destination (Join-Path $root "Chapter $chapter.docx") -Force}
}
Write-Output "Prepared updated Chapters 1 and 3 in $backup. Applied: $Apply"
